entradas.sintaxe:
SELECT colunas
FROM tabela
WHERE condicao;

entradas.exemplo:
SELECT nome, preco
FROM produtos
WHERE preco >= 200;

SELECT *
FROM pedidos
WHERE status = 'pago' AND valor_total > 500;

SELECT CAST(preco AS INTEGER) AS preco_inteiro
FROM produtos
LIMIT 5;

SELECT UPPER(TRIM(nome)) AS nome_padronizado
FROM clientes
LIMIT 5;

entradas.sintaxe:
SELECT coluna, COUNT(*)
FROM tabela
GROUP BY coluna;

entradas.exemplo:
SELECT categoria, COUNT(*) AS produtos
FROM produtos
GROUP BY categoria;

SELECT COUNT(*) FILTER (WHERE status = 'pago') AS pagos,
       COUNT(*) FILTER (WHERE status = 'cancelado') AS cancelados
FROM pedidos;

SELECT categoria, STRING_AGG(nome, ', ') AS produtos
FROM produtos
GROUP BY categoria;

entradas.sintaxe:
SELECT a.coluna, b.coluna
FROM tabela_a a
JOIN tabela_b b ON b.chave = a.chave;

SELECT a.coluna, b.coluna
FROM tabela_a a
LEFT JOIN tabela_b b ON b.chave = a.chave;

SELECT a.*
FROM tabela_a a
WHERE NOT EXISTS (
  SELECT 1 FROM tabela_b b WHERE b.chave = a.chave
);

entradas.exemplo:
SELECT c.nome
FROM clientes c
WHERE NOT EXISTS (
  SELECT 1 FROM pedidos p WHERE p.cliente_id = c.cliente_id
);

entradas.sintaxe:
SELECT colunas FROM tabela_a
UNION ALL
SELECT colunas FROM tabela_b;

entradas.exemplo:
SELECT nome, 'cliente' AS tipo FROM clientes WHERE uf = 'PE'
UNION ALL
SELECT nome, 'produto' FROM produtos WHERE categoria = 'Livros';

entradas.sintaxe:
SELECT a.coluna, b.coluna
FROM tabela_a a
RIGHT JOIN tabela_b b ON b.chave = a.chave;

SELECT a.coluna, b.coluna
FROM tabela_a a
FULL OUTER JOIN tabela_b b ON b.chave = a.chave;

SELECT a.coluna, b.coluna
FROM tabela a
JOIN tabela b ON a.chave = b.outra_chave;

SELECT a.coluna, b.coluna
FROM tabela_a a
CROSS JOIN tabela_b b;

SELECT coluna FROM tabela_a
EXCEPT
SELECT coluna FROM tabela_b;

entradas.exemplo:
SELECT categoria FROM produtos WHERE preco > 200
EXCEPT
SELECT categoria FROM produtos WHERE preco < 50;

SELECT nome
FROM clientes
WHERE email IS NULL;

SELECT strftime(criado_em, '%d/%m/%Y %H:%M') AS quando
FROM pedidos
LIMIT 5;

SELECT nome, preco
FROM produtos
WHERE preco > (SELECT AVG(preco) FROM produtos);

SELECT AVG(qtd) AS media_itens
FROM (
  SELECT pedido_id, COUNT(*) AS qtd
  FROM itens_pedido
  GROUP BY pedido_id
) AS por_pedido;

entradas.sintaxe:
WITH passo AS (
  SELECT ...
)
SELECT ... FROM passo;

WITH RECURSIVE nome AS (
  SELECT ...              -- caso base
  UNION ALL
  SELECT ... FROM nome WHERE ...  -- passo recursivo
)
SELECT * FROM nome;

entradas.exemplo:
WITH RECURSIVE numeros AS (
  SELECT 1 AS n
  UNION ALL
  SELECT n + 1 FROM numeros WHERE n < 5
)
SELECT * FROM numeros;

SELECT nome, categoria, preco,
       RANK() OVER (PARTITION BY categoria ORDER BY preco DESC) AS posicao
FROM produtos;

entradas.sintaxe:
SELECT ...
FROM tabela
QUALIFY ROW_NUMBER() OVER (...) = 1;

entradas.exemplo:
SELECT categoria, nome, preco
FROM produtos
QUALIFY ROW_NUMBER() OVER (PARTITION BY categoria ORDER BY preco DESC) = 1;

SELECT categoria, nome, preco,
       FIRST_VALUE(nome) OVER (PARTITION BY categoria ORDER BY preco DESC) AS mais_caro_da_categoria
FROM produtos;

entradas.sintaxe:
UPDATE tabela
SET coluna = valor
WHERE condicao;

entradas.exemplo:
UPDATE clientes
SET cidade = 'Campinas'
WHERE cliente_id = 999;

entradas.sintaxe:
CREATE TABLE tabela (
  coluna1 TIPO PRIMARY KEY,
  coluna2 TIPO
);

entradas.exemplo:
CREATE TABLE fornecedores (
  id INTEGER PRIMARY KEY,
  nome VARCHAR NOT NULL
);

CREATE TABLE pedidos_exemplo (
  id INTEGER PRIMARY KEY,
  cliente_id INTEGER REFERENCES clientes(cliente_id)
);
